class CardAccumulator {
    private var balance: Long = 0L
    private val entries = mutableListOf<String>()

    fun record(tag: String, amount: Long) {
        val next = balance + amount
        Thread.yield()
        balance = next
        entries.add(tag)
    }

    fun totalBalance(): Long = balance
    fun entryCount(): Int = entries.size
}

workspace_files.Main.kt:
import java.util.concurrent.CountDownLatch

fun main() {
    val acc = CardAccumulator()
    val start = CountDownLatch(1)
    val workers = (0 until 4).map { tid ->
        Thread {
            start.await()
            for (i in 0 until 100) {
                acc.record("t$tid-$i", 1L)
            }
        }
    }
    workers.forEach { it.start() }
    start.countDown()
    workers.forEach { it.join() }
    assert(acc.totalBalance() == 400L) { "Expected 400, got ${acc.totalBalance()}" }
    assert(acc.entryCount() == 400) { "Expected 400 entries, got ${acc.entryCount()}" }
    println("ALL TESTS PASSED")
}

