import java.util.ArrayDeque

class TreasuryBoundedPool(private val capacity: Int) {
    private val items = ArrayDeque<Int>((0 until capacity).toList())

    fun acquire(): Int {
        if (items.isEmpty()) {
            throw IllegalStateException("Pool exhausted without blocking")
        }
        return items.removeFirst()
    }

    fun release(item: Int) {
        items.addLast(item)
    }
}

workspace_files.Main.kt:
import java.util.concurrent.atomic.AtomicInteger

fun main() {
    val pool = TreasuryBoundedPool(4)
    val completed = AtomicInteger(0)
    val active = AtomicInteger(0)
    val maxSeen = AtomicInteger(0)
    val workers = (0 until 4).map {
        Thread {
            for (i in 0 until 25) {
                val slot = pool.acquire()
                val cur = active.incrementAndGet()
                maxSeen.accumulateAndGet(cur, Math::max)
                Thread.sleep(1)
                active.decrementAndGet()
                pool.release(slot)
                completed.incrementAndGet()
            }
        }
    }
    workers.forEach { it.start() }
    workers.forEach { it.join() }
    assert(completed.get() == 100) { "Completed=${completed.get()}" }
    assert(maxSeen.get() <= 4) { "Exceeded capacity: ${maxSeen.get()}" }
    println("ALL TESTS PASSED")
}

